import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"ADR-0031 — Pipeline di rilascio: correzioni, canale non firmato, matrice estesa (M10)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0031-release-pipeline-unsigned-channel.md","filePath":"adr/0031-release-pipeline-unsigned-channel.md"}'),l={name:"adr/0031-release-pipeline-unsigned-channel.md"};function n(d,e,c,r,s,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0031-—-pipeline-di-rilascio-correzioni-canale-non-firmato-matrice-estesa-m10" tabindex="-1">ADR-0031 — Pipeline di rilascio: correzioni, canale non firmato, matrice estesa (M10) <a class="header-anchor" href="#adr-0031-—-pipeline-di-rilascio-correzioni-canale-non-firmato-matrice-estesa-m10" aria-label="Permalink to &quot;ADR-0031 — Pipeline di rilascio: correzioni, canale non firmato, matrice estesa (M10)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.5, §3.7, §3.8.1, §4.2, §4.5, Appendice A, Appendice B, C.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-29</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§4 (supply chain, release policy: macOS firmato e notarizzato, Authenticode, immagine OCI immutabile), M7; ADR-0001, ADR-0006, ADR-0023</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, temporaneamente: rilasci desktop non firmati finché mancano i certificati → richiede una nota in <code>Specifications.md</code> da parte dell&#39;owner</td></tr></tbody></table><p><strong>Aggiornamento 2026-11-02.</strong> Lo spec registra lo <strong>stato attuale</strong> (sezione «Stato attuale»): <code>release.yml</code> costruisce e pubblica immagine, chart e installer da un tag senza firme né controlli; installer desktop non firmati come deviazione temporanea; firma, cosign, SBOM e manifest di aggiornamento da riattivare (ADR-0023 resta <em>proposta</em>); verifiche locali (ADR-0036). I punti 3, 6 e 7 della decisione valgono quando la firma sarà riattivata.</p><blockquote><p><strong>Nota (ADR-0051, accettata il 2026-11-20 e recepita in <code>Specifications.md</code> v1.8).</strong> La CLI di Wails è <strong>v3</strong> (<code>task wails-cli</code>, <code>scripts/install-wails.sh</code>, versione di <code>apps/desktop/go.mod</code>; serve solo per <code>task dev-desktop</code> e per la build Windows), non più <code>wails@v2.12.0</code>; su Linux la build non passa più <code>-tags webkit2_41</code> ma <code>-tags production,gtk3</code> (GTK 3 e WebKit2GTK 4.1). Il testo qui sotto è storico e non cambia.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p><code>release.yml</code> (installer desktop) e <code>release-images.yml</code> (immagine cloud e chart, poi assorbito in <code>release.yml</code>) sono stati scritti in M7-WP3 ma non sono mai stati eseguiti (ADR-0023, &quot;Verificato e non&quot;). Una lettura del codice ha trovato questi problemi:</p><ul><li><strong>Dockerfile:</strong> <code>services/cloud/Dockerfile</code> copia <code>.yarn</code>, che è ignorato da git. Su un checkout pulito la build dell&#39;immagine fallisce.</li><li><strong>Wails CLI:</strong> il workflow installa <code>wails@v2.12.0</code> con <code>go install</code>, ma con Go 1.27 la CLI non compila (x/tools v0.30, vedi <code>scripts/install-wails.sh</code>).</li><li><strong>Firme:</strong> con un tag, la pipeline rifiuta di proseguire se mancano Apple Developer ID, Authenticode e la chiave del manifest di aggiornamento. Oggi l&#39;owner non ha nessuno di questi certificati, quindi un rilascio non può partire.</li><li><strong>Copertura architetture:</strong> mancano Windows e Linux arm64.</li><li><strong>Immagini cloud:</strong><ul><li>la compilazione arm64 passa da QEMU ed è lenta;</li><li>le immagini escono solo dai tag;</li><li>i workflow di rilascio non attendono i test di <code>ci.yml</code>.</li></ul></li><li><strong>Placeholder:</strong> restano <code>ghcr.io/ORG</code> e <code>memobrain.example</code>.</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><p><strong>Dockerfile.</strong></p><ul><li>Copiare solo <code>.yarnrc.yml</code> (Yarn arriva da corepack).</li><li>Stage node e Go su <code>--platform=$BUILDPLATFORM</code>, con cross-compilazione <code>GOOS=$TARGETOS GOARCH=$TARGETARCH</code> (<code>CGO_ENABLED=0</code>).</li><li>Aggiungere uno stage <code>wasm</code> per il core del workbench (ADR-0030).</li></ul></li><li><p><strong>Wails CLI.</strong> Installata ovunque con <code>scripts/install-wails.sh</code>, con cache. <code>make build-desktop</code> passa <code>-tags webkit2_41</code> su Linux.</p></li><li><p><strong>Canale non firmato.</strong></p><ul><li>La variabile di repository <code>REQUIRE_SIGNING</code> (default <code>false</code>) decide cosa succede su un tag: <ul><li><code>true</code>: comportamento di ADR-0023 (fallisce se manca un segreto);</li><li><code>false</code>: firma dove i segreti esistono; altrimenti produce artefatti non firmati, con un avviso nel job summary e nelle note di rilascio. La release è marcata <code>prerelease</code> con l&#39;etichetta &quot;unsigned&quot;.</li></ul></li><li>Senza <code>UPDATE_PUBLIC_KEY</code> e <code>UPDATE_SIGNING_KEY</code> il binario è compilato con <code>updater.DisabledByBuild=1</code> e il manifest non viene pubblicato. Un client non deve mai fidarsi della chiave di sviluppo.</li><li>Con le chiavi, il flusso di ADR-0023 resta invariato.</li></ul></li><li><p><strong>Windows.</strong> Con il certificato si firma anche <code>memobrain.exe</code> prima di creare l&#39;NSIS, non solo installer e uninstaller.</p></li><li><p><strong>Matrice desktop.</strong></p><table tabindex="0"><thead><tr><th>Piattaforma</th><th>Artefatto</th><th>Build</th></tr></thead><tbody><tr><td>macOS</td><td>universal <code>.dmg</code></td><td><code>macos-15</code></td></tr><tr><td>Windows amd64</td><td>NSIS</td><td><code>windows-2022</code></td></tr><tr><td>Windows arm64</td><td>NSIS</td><td>cross-compilato: WebView2 non usa CGO</td></tr><tr><td>Linux amd64</td><td><code>.deb</code> + AppImage</td><td><code>ubuntu-24.04</code></td></tr><tr><td>Linux arm64</td><td><code>.deb</code> + AppImage</td><td><code>ubuntu-24.04-arm</code></td></tr></tbody></table></li><li><p><strong>Immagini.</strong></p><ul><li>Push su GHCR da <code>main</code> (<code>edge</code>, <code>sha-&lt;short&gt;</code>) e dai tag (<code>X.Y.Z</code>, <code>X.Y</code>, <code>latest</code> solo per le versioni stabili).</li><li>Firma cosign keyless, SBOM e provenance invariati.</li></ul></li><li><p><strong>Gate di test.</strong></p><ul><li><code>ci.yml</code> diventa riusabile (<code>workflow_call</code>) ed è il primo job di <code>release.yml</code> e <code>release-images.yml</code>.</li><li>Una sola GitHub Release per tag, con: <ul><li>gli installer;</li><li><code>SHA256SUMS</code>;</li><li>il riferimento all&#39;immagine con digest;</li><li>il riferimento al chart.</li></ul></li><li>La release resta in bozza se <code>RELEASE_AUTO_PUBLISH</code> non è <code>true</code>.</li></ul></li><li><p><strong>Placeholder.</strong></p><ul><li><code>ghcr.io/ORG</code> diventa <code>ghcr.io/e2br</code> (owner del repository, minuscolo).</li><li>La homepage del <code>.deb</code> è l&#39;URL del repository GitHub. <code>UPDATE_BASE_URL</code> resta una variabile di repository, e il valore predefinito <code>updates.memobrain.example</code> in <code>internal/updater/key.go</code> non si usa più nelle build di rilascio: senza chiavi l&#39;updater è compilato fuori, con le chiavi la variabile è passata con ldflags.</li><li>Le icone segnaposto restano finché l&#39;owner non fornisce l&#39;artwork.</li></ul></li></ol><h2 id="semplificazione-dei-workflow-2026-10-30" tabindex="-1">Semplificazione dei workflow (2026-10-30) <a class="header-anchor" href="#semplificazione-dei-workflow-2026-10-30" aria-label="Permalink to &quot;Semplificazione dei workflow (2026-10-30)&quot;">​</a></h2><p>Dopo i primi run reali i workflow sono ridotti a due, più <code>security.yml</code> (invariato). Una verifica iniziale separata (<code>verify.yml</code>) era stata introdotta e poi tolta dall&#39;owner; l&#39;owner ha poi chiesto che <strong>build e pubblicazione avvengano solo da un tag</strong> e che la CI non costruisca nulla:</p><ul><li><code>ci.yml</code> (ogni commit, su qualsiasi branch): lint, tipi e test unitari Go e TypeScript, controllo del codice generato e della matrice di parità. Nessuna build.</li><li><code>release.yml</code> (solo tag <code>vX.Y.Z[-pre]</code>): installer macOS, Windows e Linux, immagine e chart Helm pubblicati su GHCR e firmati, una sola GitHub Release. Non esiste più il dry run da <code>workflow_dispatch</code>.</li></ul><p><code>release-images.yml</code> è stato rimosso, e con esso l&#39;immagine <code>edge</code> da <code>main</code>. Fuori dalla CI automatica restano, da lanciare a mano, le suite lente: Playwright (<code>make e2e</code>), integrazione con testcontainers (<code>make test-integration</code>), sync e2e a due dispositivi, test del core sotto WASM (<code>make test-wasm</code>) e il budget di dimensione del core (applicato comunque dalla build dell&#39;immagine). Si perde quindi la copertura continua di quelle suite: è il prezzo scelto per avere una CI veloce e leggibile.</p><h2 id="stato-attuale-2026-11-01" tabindex="-1">Stato attuale (2026-11-01) <a class="header-anchor" href="#stato-attuale-2026-11-01" aria-label="Permalink to &quot;Stato attuale (2026-11-01)&quot;">​</a></h2><p>Dopo la semplificazione del 2026-10-30 la pipeline è stata ridotta ancora (1.2.2–1.2.4, vedi <code>CHANGELOG.md</code>):</p><ul><li><code>ci.yml</code> e <code>security.yml</code> sono stati rimossi: non c&#39;è più un gate di CI né in <code>release.yml</code> né sulle push. Le verifiche si fanno in locale con <code>task ci</code> (ADR-0036).</li><li><code>release.yml</code> è l&#39;unico workflow: su un tag pubblica immagine multi-arch e chart Helm su GHCR, costruisce gli installer e crea una GitHub Release pubblicata con <code>SHA256SUMS</code>. Usa solo il <code>GITHUB_TOKEN</code> del run.</li><li><strong>Non firma nulla</strong>: niente <code>REQUIRE_SIGNING</code>, firme Apple e Authenticode, cosign, SBOM, attestazioni né manifest di aggiornamento; l&#39;updater resta compilato fuori (<code>ALLOW_UNSIGNED_UPDATES=1</code>). Il canale non firmato descritto sopra è quindi l&#39;unico canale, e i punti 3, 6 e 7 della decisione sono da riattivare (<code>docs/release/README.md</code>, «Da riattivare»).</li><li>Matrice desktop: macOS universale su <code>macos-15</code>, Windows amd64 su <code>windows-2022</code>, Linux amd64 su <code>ubuntu-24.04</code>. Windows arm64 è stato tolto nella 1.2.3; Linux arm64 non è mai entrato.</li><li>Tutte le action sono alla major che gira su Node.js 24 (1.2.4).</li></ul><p>Le sezioni seguenti descrivono l&#39;implementazione e le verifiche di M10 e restano come storia.</p><h2 id="implementazione-m10" tabindex="-1">Implementazione (M10) <a class="header-anchor" href="#implementazione-m10" aria-label="Permalink to &quot;Implementazione (M10)&quot;">​</a></h2><ul><li><code>release.yml</code> è l&#39;unico workflow di un tag: <code>meta</code> (versione, quali firme sono attive, matrice) → <code>ci</code> (richiama <code>ci.yml</code>) → <code>images</code> (richiama <code>release-images.yml</code>) e <code>build</code> in parallelo → <code>release</code> (una sola GitHub Release).</li><li>La matrice è calcolata in <code>meta</code>. Linux arm64 entra solo se la variabile <code>LINUX_ARM64_RUNNER</code> nomina un runner (WebKitGTK è CGO, serve un host arm64), perché la disponibilità di <code>ubuntu-24.04-arm</code> dipende dalla visibilità del repository.</li><li><code>scripts/release/build-desktop.sh</code> ora legge <code>ARCH</code>, compila l&#39;updater fuori con <code>ALLOW_UNSIGNED_UPDATES=1</code> quando mancano le chiavi, e su Windows firma <code>memobrain.exe</code> e poi esegue <code>makensis</code> direttamente. Per farlo <code>scripts/release/nsis-render.go</code> rende <code>wails_tools.nsh</code> (un template Go) come fa <code>wails build -nsis</code>, e lo script scarica il bootstrapper di WebView2.</li><li><code>release-images.yml</code> ha tre modi: <code>build</code> (PR, dispatch: niente push), <code>edge</code> (push su <code>main</code>) e <code>release</code> (richiamato con <code>version</code>).</li><li>Trovato e corretto durante la verifica: <code>ci.yml</code> aveva un nome di job con <code>:</code> non quotato (YAML non valido: il workflow non sarebbe mai partito); la variabile <code>MEMOBRAIN_SIGNTOOL_CMD</code> non impostata arrivava a NSIS come testo letterale e <code>!finalize</code> la eseguiva come comando.</li></ul><h2 id="verificato-e-non" tabindex="-1">Verificato e non <a class="header-anchor" href="#verificato-e-non" aria-label="Permalink to &quot;Verificato e non&quot;">​</a></h2><ul><li><strong>Verificato su GitHub (dry run <code>workflow_dispatch</code> dal branch <code>m10-release-dryrun</code>, versione <code>0.0.0-dryrun.3</code>, senza segreti, senza CI, senza immagini):</strong> <code>meta</code>, build di macOS universale, Windows amd64, Windows arm64 (cross-compilato), Linux amd64 (<code>.deb</code> e AppImage), job <code>release</code> (checksum, SBOM) e raccolta degli artefatti. Il run completo è verde in circa 6 minuti, e produce installer da 62 MB (Linux), 65 MB (macOS), 33 MB (Windows amd64) e 32 MB (Windows arm64). Gli installer sono <strong>non firmati</strong>, come previsto.</li><li><strong>Difetti trovati dai dry run e corretti:</strong><ol><li>Windows: <code>corepack enable</code> prima di <code>setup-node</code> perdeva lo shim di Yarn 4 (corretto anche nel job <code>desktop-build</code> di <code>ci.yml</code>).</li><li>Linux: <code>nfpm</code> non espande <code>${STAGE}</code> nei percorsi dei file (ora reso da <code>package-linux.sh</code>).</li><li>Linux: <code>appimagetool</code> richiede <code>desktop-file-utils</code>.</li><li>(Prima dei dry run) <code>ci.yml</code> aveva un nome di job con <code>:</code> non quotato, e <code>MEMOBRAIN_SIGNTOOL_CMD</code> non impostata arrivava a NSIS come testo letterale.</li></ol></li><li><strong>Verificato in locale:</strong> <code>actionlint</code>, <code>bash -n</code>, installer NSIS arm64 con <code>makensis</code> da macOS (template reso, exe finto, firma simulata), <code>helm lint</code>.</li><li><strong>Non verificato:</strong><ul><li><strong>L&#39;immagine Docker</strong>: nel dry run il job <code>images</code> è saltato per costruzione, e la build locale <code>docker buildx build --platform linux/amd64,linux/arm64</code> è fallita due volte per la rete di Docker (<code>unexpected EOF</code> da <code>sum.golang.org</code>, <code>ERR_SOCKET_CLOSED_BEFORE_CONNECTION</code> da yarn), non per il Dockerfile, ma resta senza esito. Va provata da GitHub (push su <code>main</code>, che pubblica <code>edge</code>, oppure un tag).</li><li>Il gate <code>ci.yml</code> richiamato da <code>release.yml</code> (saltato nel dry run) e <code>ci.yml</code> stesso dopo le modifiche.</li><li>Linux arm64 (senza <code>LINUX_ARM64_RUNNER</code> non entra nella matrice; il repository è privato).</li><li>Firma Authenticode e Apple, notarizzazione, firma di <code>memobrain.exe</code>, manifest di aggiornamento firmato.</li><li>Cosign, attestazioni, push su GHCR, visibilità dei package, chart OCI, i <code>permissions</code> e gli <code>outputs</code> del reusable workflow.</li><li>Che gli installer <strong>si avviino</strong> su Windows, macOS e Linux (nessuno è stato eseguito).</li><li>La creazione della GitHub Release (nel dry run non si crea).</li></ul></li><li><strong>Da fornire dall&#39;owner:</strong> certificati di firma, icone definitive, <code>LINUX_ARM64_RUNNER</code>, rendere pubblici i package GHCR.</li></ul><h2 id="proposta-di-modifica-dello-spec" tabindex="-1">Proposta di modifica dello spec <a class="header-anchor" href="#proposta-di-modifica-dello-spec" aria-label="Permalink to &quot;Proposta di modifica dello spec&quot;">​</a></h2><p>§4 (release policy): &quot;Fino alla disponibilità dei certificati (Apple Developer ID, Authenticode) gli installer possono essere pubblicati come prerelease non firmate, con avviso esplicito. L&#39;aggiornamento automatico resta disattivato in queste build. Un rilascio stabile richiede <code>REQUIRE_SIGNING=true</code>.&quot;</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Bloccare ogni rilascio fino all&#39;arrivo dei certificati</strong>: scartata, l&#39;owner vuole installer pubblicabili subito.</li><li><strong>Firma self-signed o ad-hoc (<code>codesign -s -</code>)</strong>: scartata, non elimina gli avvisi di Gatekeeper e SmartScreen e dà un falso senso di sicurezza. L&#39;ad-hoc resta solo per la build universale macOS, dove è necessario.</li><li><strong>goreleaser</strong>: scartato, gli script esistenti coprono già Wails, nfpm, AppImage e il manifest. Introdurlo ora aggiungerebbe un&#39;altra configurazione da mantenere.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Gli installer non firmati mostrano gli avvisi del sistema operativo. La guida utente deve spiegare come aprirli: macOS &quot;Apri&quot; dal menu contestuale, Windows SmartScreen &quot;Ulteriori informazioni&quot;.</li><li>Le build non firmate non si aggiornano da sole: l&#39;utente scarica la versione nuova a mano.</li><li>Con l&#39;arrivo dei segreti basta impostare <code>REQUIRE_SIGNING=true</code>, senza toccare i workflow.</li><li>Il package GHCR va reso pubblico a mano dopo il primo push (passo documentato in <code>docs/release/README.md</code>).</li></ul>',27)])])}const g=o(l,[["render",n]]);export{p as __pageData,g as default};
